import type Anthropic from "@anthropic-ai/sdk";
import { type Action, LEARNING_SYSTEM, seedTurn } from "./prompt.ts";
import type { Anchor, Mark, ThreadId } from "./selection.ts";
import type { Tool, ToolName, TurnResult } from "./thread.ts";
import { type Socket, Thread } from "./thread.ts";

export type { Action };

/** `anchor.thread` is the parent, so the link upward is the highlight itself. */
export type Origin = { anchor: Anchor; action: Action };

/** What a child thread is given beyond its seed. */
export type ChildOpts = {
  tools?: Record<ToolName, Tool>;
  /** The rendered knowledge graph, injected into the seed of a top-level
   * learning thread. */
  graph?: string;
  yieldSchema?: Anthropic.Tool.InputSchema | "text";
};

export type TreeNode = {
  id: ThreadId;
  /** null only for the root task thread. */
  origin: Origin | null;
  thread: Thread;
  /** Creation order; each child's `origin.anchor` is its highlight. */
  children: ThreadId[];
  activeChild: ThreadId | null;
  draft: string;
};

/** The tree of threads. Every thread but the root was opened from a
 * passage of its parent, so a thread and the highlight over its parent are the
 * same edge seen from either end. Threads are never destroyed or reparented. */
export class ThreadTree {
  private readonly threads = new Map<ThreadId, TreeNode>();
  private nextId = 0;
  readonly root: ThreadId;
  private readonly socket: Socket;
  /** Attached to every thread the tree owns, so a stream anywhere in the
   * tree re-syncs the app. */
  private readonly onChange: () => void;

  constructor(socket: Socket, root: Thread, onChange: () => void) {
    this.socket = socket;
    this.onChange = onChange;
    this.root = this.add(null, root);
  }

  get(id: ThreadId): TreeNode {
    const node = this.threads.get(id);
    if (!node) throw new Error(`unknown thread ${id}`);
    return node;
  }

  /** Seeds a child thread from the parent's own seed plus its transcript
   * up to `anchor`, links it in, and makes it the parent's active child. The
   * caller starts it: the tree does not own the request lifecycle. */
  open(anchor: Anchor, action: Action, opts: ChildOpts = {}): ThreadId {
    const parent = this.get(anchor.thread);
    const thread = new Thread(this.socket, {
      system: LEARNING_SYSTEM,
      seed: seedTurn(
        parent.thread.seed,
        parent.thread.messages,
        anchor,
        action,
        opts.graph,
      ),
      tools: opts.tools,
      yieldSchema: opts.yieldSchema,
    });
    const id = this.add({ anchor, action }, thread);
    parent.children.push(id);
    parent.activeChild = id;
    return id;
  }

  /** What a child thread settled with, once it has yielded. The parent renders
   * threads it never awaited, so the settled value has to be readable here. */
  result(id: ThreadId): TurnResult | undefined {
    return this.get(id).thread.result;
  }

  /** The highlights to draw over `id`'s transcript: one per child. */
  marks(id: ThreadId): Mark[] {
    return this.get(id).children.map((child) => {
      const origin = this.get(child).origin;
      if (!origin) throw new Error("child thread without an origin");
      return { thread: child, anchor: origin.anchor };
    });
  }

  /** root -> id, for the depth indicator. */
  path(id: ThreadId): ThreadId[] {
    const out: ThreadId[] = [];
    let at: ThreadId | undefined = id;
    while (at) {
      out.unshift(at);
      at = this.get(at).origin?.anchor.thread;
    }
    return out;
  }

  private add(origin: Origin | null, thread: Thread): ThreadId {
    const id = `t${this.nextId++}` as ThreadId;
    thread.onChange = this.onChange;
    this.threads.set(id, {
      id,
      origin,
      thread,
      children: [],
      activeChild: null,
      draft: "",
    });
    return id;
  }
}

import type Anthropic from "@anthropic-ai/sdk";
import type { ClientMessage, ServerFrame } from "@edulab/iso/protocol.ts";

const MODEL = "claude-opus-4-5";
const MAX_TOKENS = 16384;
// Task mode: the agent is here to get the user's work done. Learning mode is
// the secondary mode we layer on top of a transcript this produces, so this
// prompt must not pre-emptively tutor - the whole premise of the prototype is
// that a user watching a capable agent work becomes a passive observer.
const SYSTEM = [
  "You are a capable engineering assistant helping the user complete a task.",
  "Work the problem directly: make concrete decisions, write real code, and",
  "state your reasoning as you go rather than asking the user to supply it.",
  "Be concise. Do not quiz the user, do not pad explanations for a beginner,",
  "and do not check whether they are following - just do the work well.",
].join(" ");

// Unattended mode: nobody is reading the transcript as it streams, so a
// question to the user is a dead end. The only exit is the yield tool.
const AUTONOMOUS_SYSTEM = [
  "You are a capable engineering assistant running unattended: there is no",
  "user to answer questions, and nothing you say outside the yield tool will",
  "be read. Work the problem to completion, making whatever decisions you",
  "need without asking, and finish by calling the yield tool exactly once",
  "with your result. Do not stop for confirmation and do not ask questions.",
].join(" ");

const MAX_RESTARTS = 5;
const restartNudge = (attempt: number, max: number) =>
  `You stopped without yielding. Nobody read that message. Complete the task and call the yield tool when you are done. (auto-restart ${attempt}/${max})`;

const YIELD = "yield";
const DEFAULT_YIELD_SCHEMA: Anthropic.Tool.InputSchema = {
  type: "object",
  properties: {
    result: {
      type: "string",
      description: "The result to return to whoever spawned this thread.",
    },
  },
  required: ["result"],
};

export type ToolCall = {
  id: string;
  name: string;
  /** Parsed from the streamed json; undefined while still streaming or if it
   * never parsed. */
  input: Record<string, unknown> | undefined;
  /** Raw accumulated json, so a partial call is still renderable. */
  inputJson: string;
  /** Derived from the paired tool_result block in the next user turn; absent
   * while the tool is still running. */
  result: ToolResult | undefined;
};

export type YieldValue =
  | { type: "text"; text: string }
  | { type: "structured"; value: Record<string, unknown> };

export type TurnResult =
  | { type: "completed" }
  | { type: "yielded"; value: YieldValue }
  | { type: "error"; message: string };

export type ThreadOpts = {
  system?: string;
  initialTurns?: Anthropic.MessageParam[];
  seed?: string;
  tools?: Record<ToolName, Tool>;
  /** Present => the yield tool is offered. `"text"` uses the default
   * `{ result: string }` schema and settles with a text value; a schema
   * settles with the whole input object. */
  yieldSchema?: Anthropic.Tool.InputSchema | "text";
};

/** The key of a tool in the record handed to a thread; also what the model
 * sends back as `tool_use.name`. */
export type ToolName = string & { readonly __brand: "ToolName" };

export type ToolResult =
  | { status: "ok"; text: string }
  | { status: "error"; error: string };
/** A tool the thread can run, client side. */
export type Tool = {
  spec: Anthropic.Tool;
  execute(input: Record<string, unknown>): Promise<ToolResult>;
};

/** Keys a set of tools by name. `Record<ToolName, Tool>` is a mapped type over
 * a branded string, so an object literal cannot be written for it directly. */
export function toolset(...tools: ReadonlyArray<Tool>): Record<ToolName, Tool> {
  return Object.fromEntries(tools.map((t) => [t.spec.name, t]));
}

/** One entry of the derived transcript: a block, not a turn. A single agent
 * turn can produce prose, a tool call, and more prose, and the transcript shows
 * it that way. */
export type Message =
  | { type: "text"; role: "user" | "assistant"; text: string }
  | { type: "tool_use"; role: "assistant"; call: ToolCall };

/** Anchors index into text entries only, so everything else has no text. */
export function messageText(message: Message): string {
  return message.type === "text" ? message.text : "";
}

/** A block of the assistant turn currently streaming. */
type PendingBlock =
  | { type: "text"; text: string }
  | {
      type: "tool_use";
      id: string;
      name: string;
      inputJson: string;
      input: Record<string, unknown> | undefined;
    };

/** The subset of WebSocket the thread uses, so tests can stand in for it. */
export type Socket = {
  send(data: string): void;
  addEventListener(
    type: "message",
    listener: (e: MessageEvent<string>) => void,
  ): void;
};

export type ThreadResult<Value> =
  | { status: "ok"; result: Value }
  | { status: "error"; error: string };

export type RunThreadOpts = {
  prompt: string;
  tools?: Record<ToolName, Tool>;
  yieldSchema: Anthropic.Tool.InputSchema | "text";
  system?: string;
  /** How many times a turn that ends without a yield is nudged back to work. */
  maxRestarts?: number;
};

/** Runs a thread to completion with no user in the loop: the seed prompt goes
 * in, tools run client side, and the settled yield comes back. A turn that
 * ends without yielding is restarted rather than accepted. */
export function runThread(
  socket: Socket,
  opts: RunThreadOpts & { yieldSchema: "text" },
): Promise<ThreadResult<string>>;
export function runThread<Value extends Record<string, unknown>>(
  socket: Socket,
  opts: RunThreadOpts & { yieldSchema: Anthropic.Tool.InputSchema },
): Promise<ThreadResult<Value>>;
export async function runThread(
  socket: Socket,
  opts: RunThreadOpts,
): Promise<ThreadResult<string | Record<string, unknown>>> {
  const maxRestarts = opts.maxRestarts ?? MAX_RESTARTS;
  const thread = new Thread(socket, {
    system: opts.system ?? AUTONOMOUS_SYSTEM,
    seed: opts.prompt,
    tools: opts.tools,
    yieldSchema: opts.yieldSchema,
  });
  let result = await thread.start();
  for (let attempt = 1; result.type === "completed"; attempt++) {
    if (attempt > maxRestarts) {
      return {
        status: "error",
        error: `thread stopped without yielding after ${maxRestarts} restarts`,
      };
    }
    result = await thread.send(restartNudge(attempt, maxRestarts));
  }
  return result.type === "yielded"
    ? {
        status: "ok",
        result:
          result.value.type === "text" ? result.value.text : result.value.value,
      }
    : { status: "error", error: result.message };
}

export class Thread {
  private readonly turns: Anthropic.MessageParam[];
  private pending:
    | {
        requestId: string;
        blocks: PendingBlock[];
        stopReason: string | null;
      }
    | undefined;
  /** Bumped whenever the log or the streaming block changes, so `messages` can
   * be recomputed lazily rather than on every delta. */
  private version = 0;
  private cache:
    | { version: number; messages: ReadonlyArray<Message> }
    | undefined;
  private settle:
    | ((content: Anthropic.ContentBlockParam[]) => void)
    | undefined;
  /** True for the whole agent turn, including while tools execute between
   * requests - the UI and the send guard care about the turn, not the request. */
  private running = false;
  /** Set when a request ends in a done/error frame, which ends the turn even
   * if tools were requested. */
  private failed = false;
  /** tool_use ids whose streamed json never parsed. The log has to carry an
   * object the API would accept, so this is the only place that knowledge
   * survives the commit. */
  private readonly unparsed = new Set<string>();
  onChange: (() => void) | undefined;

  private readonly socket: Socket;
  private readonly system: string;
  private readonly tools: Record<ToolName, Tool>;
  /** Present => the yield tool is offered and the turn can settle with data. */
  private readonly yieldSchema: Anthropic.Tool.InputSchema | "text" | undefined;
  private settled: TurnResult | undefined;
  /** Turn 0 when present: sent like any other turn, never rendered. */
  readonly seed: string | undefined;

  constructor(socket: Socket, opts: ThreadOpts = {}) {
    this.socket = socket;
    this.system = opts.system ?? SYSTEM;
    this.tools = opts.tools ?? {};
    this.yieldSchema = opts.yieldSchema;
    this.seed = opts.seed;
    this.turns = opts.seed
      ? [{ role: "user", content: opts.seed }]
      : [...(opts.initialTurns ?? [])];
    socket.addEventListener("message", (e: MessageEvent<string>) => {
      this.handleFrame(JSON.parse(e.data) as ServerFrame);
    });
  }

  /** The derived transcript: the log flattened into blocks, plus whatever is
   * currently streaming. The log stays the wire format; nothing is ever
   * converted back out of `Message`. */
  get messages(): ReadonlyArray<Message> {
    if (this.cache?.version === this.version) return this.cache.messages;
    const messages = project(
      this.seed ? this.turns.slice(1) : this.turns,
      this.pending?.blocks,
    );
    this.cache = { version: this.version, messages };
    return messages;
  }

  get inFlight(): boolean {
    return this.running;
  }

  /** The settled yield, once the thread has produced one. */
  get result(): TurnResult | undefined {
    return this.settled;
  }

  send(text: string): Promise<TurnResult> {
    if (this.running) return Promise.resolve({ type: "completed" });
    this.turns.push({ role: "user", content: text });
    this.version++;
    return this.run();
  }

  /** Requests a reply to the turns already present - the seeded first turn of
   * a learning thread, which the user never typed. */
  start(): Promise<TurnResult> {
    if (this.running || this.turns.length === 0)
      return Promise.resolve({ type: "completed" });
    return this.run();
  }

  /** One agent turn: request, execute whatever tools the model asked for,
   * request again, until it replies without calling any. */
  private async run(): Promise<TurnResult> {
    this.running = true;
    this.failed = false;
    try {
      for (;;) {
        const content = await this.request();
        if (this.failed) return { type: "error", message: "request ended" };
        const calls = content.filter(
          (block): block is Anthropic.ToolUseBlockParam =>
            block.type === "tool_use",
        );
        if (calls.length === 0) return { type: "completed" };
        // Every tool_use must be answered by exactly one tool_result in the
        // immediately following user turn, in request order, or the next
        // request is rejected outright.
        const results = await Promise.all(
          calls.map((call) => this.execute(call)),
        );
        this.turns.push({ role: "user", content: results });
        this.version++;
        this.onChange?.();
        // Yield is not special-cased during execution: the whole batch runs and
        // every result lands in the log, and only then does the turn stop.
        const yielded = calls.find((call) => this.isYield(call.name));
        if (yielded) {
          const result: TurnResult = {
            type: "yielded",
            value: this.yieldValue(
              (yielded.input ?? {}) as Record<string, unknown>,
            ),
          };
          this.settled = result;
          return result;
        }
      }
    } finally {
      this.running = false;
      this.onChange?.();
    }
  }

  private isYield(name: string): boolean {
    return this.yieldSchema !== undefined && name === YIELD;
  }

  private yieldValue(input: Record<string, unknown>): YieldValue {
    return this.yieldSchema === "text"
      ? { type: "text", text: String(input.result ?? "") }
      : { type: "structured", value: input };
  }

  private toolSpecs(): Anthropic.Tool[] {
    const specs = Object.values(this.tools).map((tool) => tool.spec);
    if (this.yieldSchema !== undefined) {
      specs.push({
        name: YIELD,
        description:
          "Finish this thread and return your result to whoever spawned it. Call this exactly once, when you are done; do not call it before you have finished the work.",
        input_schema:
          this.yieldSchema === "text" ? DEFAULT_YIELD_SCHEMA : this.yieldSchema,
      });
    }
    return specs;
  }

  private async execute(
    call: Anthropic.ToolUseBlockParam,
  ): Promise<Anthropic.ToolResultBlockParam> {
    const result: ToolResult = this.unparsed.has(call.id)
      ? { status: "error", error: "could not parse tool input" }
      : this.isYield(call.name)
        ? // Echoing the yielded payload back at the model only spends tokens.
          { status: "ok", text: "Yield acknowledged." }
        : await runTool(this.tools[call.name as ToolName], call);
    return {
      type: "tool_result",
      tool_use_id: call.id,
      content: result.status === "ok" ? result.text : result.error,
      is_error: result.status === "error",
    };
  }

  /** Resolves with the assistant content the request committed. */
  private request(): Promise<Anthropic.ContentBlockParam[]> {
    const specs = this.toolSpecs();
    const requestId = crypto.randomUUID();
    this.pending = { requestId, blocks: [], stopReason: null };
    this.version++;
    const message: ClientMessage = {
      type: "start",
      requestId,
      params: {
        model: MODEL,
        max_tokens: MAX_TOKENS,
        system: this.system,
        stream: true,
        messages: [...this.turns],
        ...(specs.length > 0 ? { tools: specs } : {}),
      },
    };
    this.socket.send(JSON.stringify(message));
    this.onChange?.();
    return new Promise<Anthropic.ContentBlockParam[]>((resolve) => {
      this.settle = resolve;
    });
  }

  handleFrame(frame: ServerFrame): void {
    const pending = this.pending;
    if (!pending || frame.requestId !== pending.requestId) return;
    switch (frame.type) {
      case "event":
        this.handleEvent(frame.event);
        break;
      case "done":
      case "error":
        this.failed = true;
        // A turn that ends without a message_stop still commits whatever text
        // arrived, so the next turn's array stays valid.
        this.commit();
        break;
    }
    this.version++;
    this.onChange?.();
  }

  private handleEvent(event: Anthropic.RawMessageStreamEvent): void {
    const pending = this.pending;
    if (!pending) return;
    // RawMessageStreamEvent is an open union we forward verbatim from the SDK,
    // so an unrecognized event warns rather than throwing - a version bump
    // should not break a stream we can otherwise render.
    switch (event.type) {
      case "content_block_start": {
        const block = startBlock(event.content_block);
        if (block) pending.blocks[event.index] = block;
        break;
      }
      case "content_block_delta":
        appendDelta(pending.blocks[event.index], event.delta);
        break;
      case "content_block_stop": {
        const block = pending.blocks[event.index];
        // The model's json only becomes readable once it is complete; a stream
        // cut short leaves `input` undefined and the partial json in place.
        if (block?.type === "tool_use")
          block.input = parseInput(block.inputJson);
        break;
      }
      case "message_delta":
        pending.stopReason = event.delta.stop_reason;
        break;
      case "message_stop":
        this.commit();
        break;
      case "message_start":
        break;
      default:
        console.warn("unhandled stream event", event);
    }
  }

  private commit(): void {
    const pending = this.pending;
    if (!pending) return;
    this.pending = undefined;
    for (const block of pending.blocks) {
      if (block?.type === "tool_use" && block.input === undefined) {
        this.unparsed.add(block.id);
      }
    }
    const content = commitBlocks(pending.blocks);
    // MessageParam content must be non-empty, so an empty response is dropped.
    if (content.length > 0) this.turns.push({ role: "assistant", content });
    this.settle?.(content);
    this.settle = undefined;
  }
}

async function runTool(
  tool: Tool | undefined,
  call: Anthropic.ToolUseBlockParam,
): Promise<ToolResult> {
  if (!tool) return { status: "error", error: `unknown tool: ${call.name}` };
  // Validating input against input_schema is the API's job; the client only
  // checks that the streamed json parsed at all, which it did by here.
  const input = (call.input ?? {}) as Record<string, unknown>;
  try {
    return await tool.execute(input);
  } catch (error) {
    return { status: "error", error: String(error) };
  }
}

function commitBlocks(
  blocks: ReadonlyArray<PendingBlock>,
): Anthropic.ContentBlockParam[] {
  const out: Anthropic.ContentBlockParam[] = [];
  for (const block of blocks) {
    if (!block) continue;
    if (block.type === "text") {
      if (block.text.length > 0) out.push({ type: "text", text: block.text });
    } else {
      out.push({
        type: "tool_use",
        id: block.id,
        name: block.name,
        input: block.input ?? {},
      });
    }
  }
  return out;
}

/** Flattens the log into transcript entries, pairing each tool call with the
 * result that arrives in the following user turn. */
function project(
  turns: ReadonlyArray<Anthropic.MessageParam>,
  streaming: ReadonlyArray<PendingBlock> | undefined,
): ReadonlyArray<Message> {
  const results = new Map<string, ToolResult>();
  for (const turn of turns) {
    if (typeof turn.content === "string") continue;
    for (const block of turn.content) {
      if (block.type === "tool_result") {
        results.set(block.tool_use_id, toolResult(block));
      }
    }
  }

  const out: Message[] = [];
  for (const turn of turns) {
    const role = turn.role === "assistant" ? "assistant" : "user";
    if (typeof turn.content === "string") {
      out.push({ type: "text", role, text: turn.content });
      continue;
    }
    for (const block of turn.content) {
      switch (block.type) {
        case "text":
          out.push({ type: "text", role, text: block.text });
          break;
        case "tool_use":
          out.push({
            type: "tool_use",
            role: "assistant",
            call: {
              id: block.id,
              name: block.name,
              input: block.input as Record<string, unknown> | undefined,
              inputJson: JSON.stringify(block.input ?? {}),
              result: results.get(block.id),
            },
          });
          break;
        default:
          // tool_result blocks are shown on the call they answer, and the
          // remaining variants are not produced by this prototype.
          break;
      }
    }
  }

  for (const block of streaming ?? []) {
    if (!block) continue;
    if (block.type === "text") {
      if (block.text.length > 0) {
        out.push({ type: "text", role: "assistant", text: block.text });
      }
    } else {
      out.push({
        type: "tool_use",
        role: "assistant",
        call: {
          id: block.id,
          name: block.name,
          input: block.input,
          inputJson: block.inputJson,
          result: undefined,
        },
      });
    }
  }
  return out;
}

function toolResult(block: Anthropic.ToolResultBlockParam): ToolResult {
  const content = block.content;
  const text =
    typeof content === "string"
      ? content
      : (content ?? [])
          .map((part) => (part.type === "text" ? part.text : ""))
          .join("");
  return block.is_error
    ? { status: "error", error: text }
    : { status: "ok", text };
}

function parseInput(json: string): Record<string, unknown> | undefined {
  if (json.trim() === "") return {};
  try {
    const parsed = JSON.parse(json) as unknown;
    return typeof parsed === "object" && parsed !== null
      ? (parsed as Record<string, unknown>)
      : undefined;
  } catch {
    return undefined;
  }
}

/** Thinking blocks are not requested by this prototype, so they are warned
 * about rather than silently dropped - when we add them, this is where they
 * surface. */
function startBlock(block: Anthropic.ContentBlock): PendingBlock | undefined {
  switch (block.type) {
    case "text":
      return { type: "text", text: block.text };
    case "tool_use":
      return {
        type: "tool_use",
        id: block.id,
        name: block.name,
        inputJson: "",
        input: undefined,
      };
    default:
      console.warn("unhandled content block", block);
      return undefined;
  }
}

function appendDelta(
  block: PendingBlock | undefined,
  delta: Anthropic.RawContentBlockDelta,
): void {
  switch (delta.type) {
    case "text_delta":
      if (block?.type === "text") block.text += delta.text;
      break;
    case "input_json_delta":
      if (block?.type === "tool_use") block.inputJson += delta.partial_json;
      break;
    default:
      console.warn("unhandled content block delta", delta);
  }
}

import { type Anchor, anchorText, type ThreadId } from "./selection.ts";
import type { Message } from "./thread.ts";
import type { ThreadTree } from "./threads.ts";

export type Action =
  | { type: "explain" }
  | { type: "quiz" }
  | { type: "query"; text: string };

/** Learning mode: the agent is explaining work that already happened, to a
 * user who chose the passage they are stuck on. */
export const LEARNING_SYSTEM = [
  "You are helping a user understand engineering work that was done for them.",
  "They will show you a transcript and point at a passage they picked out.",
  "Answer about that passage specifically, in plain language, and assume the",
  "user has not followed the reasoning that produced it. Be concise, and do",
  "not restate the whole transcript back to them.",
  "",
  "You may be shown a knowledge graph: what we believe this user already",
  "understands, one line per node and edge, each with an id and a level on the",
  "scale 1 unfamiliar, 2 emerging, 3 working, 4 fluent. Pitch your answer to",
  "it: build on what they are fluent in and slow down on what they are not.",
  "The overview is titles only, so call the `get` tool with the ids of",
  "anything you are about to lean on to read its full description and the",
  "notes on this user. You cannot change the graph; do not offer to.",
].join(" ");

/** The single synthetic user turn seeding a learning thread. `seed` is the
 * parent's own seed and is emitted verbatim - wrapping or re-labelling it
 * would nest the framing one layer deeper at every level. */
export function seedTurn(
  seed: string | undefined,
  messages: ReadonlyArray<Message>,
  anchor: Anchor,
  action: Action,
  graph?: string,
): string {
  const visible = messages.slice(0, anchor.end.msg + 1);
  const sections = [];
  // Only the topmost learning thread renders the graph: a deeper thread's
  // `seed` is its parent's, which already carries it, and repeating it would
  // show the model the same overview once per level.
  if (seed) sections.push(seed);
  else if (graph)
    sections.push(`What this user already understands:\n${graph}`);
  sections.push(transcript(visible));
  sections.push(
    `The user then selected: "${anchorText(anchor, visible)}"\n${question(action)}`,
  );
  return sections.join("\n\n");
}

/** Extraction mode: one detached pass over the whole session, whose only
 * output is the graph it writes through its tools. Nobody reads its prose. */
export const EXTRACT_SYSTEM = [
  "You are reading a session in which an engineering agent did some work for",
  "a user, together with the follow-up threads the user opened on passages",
  "they did not understand. Your job is to maintain a knowledge graph of the",
  "domains this session touched.",
  "One node per concept - an idea a person can understand or fail to",
  "understand - never one per file, message or line of code. Add edges for the",
  "relationships that matter: what builds on what, what is an instance of",
  "what. Set the level from what the user's own questions and answers reveal,",
  "on the scale 1 unfamiliar, 2 emerging, 3 working, 4 fluent, defaulting to 1",
  "for a concept they never engaged with. The scale cannot express a",
  "misconception - a confidently held wrong belief reads as fluent - so put",
  "misconceptions, and anything else about how this user holds the idea, in",
  "`notes`.",
  "The current graph is shown below. Extend it: update the nodes that already",
  "exist rather than minting a second node for the same concept. Work in",
  "batches, and stop when the graph reflects the session. Nothing you say",
  "outside the tools is read.",
].join(" ");

/** The whole session as one prompt: every thread depth-first, each child
 * labelled with what the user asked and the passage they asked it about. The
 * questions the user asked are the evidence about what they did not
 * understand, so they have to survive into the seed. */
export function renderTree(tree: ThreadTree, graph?: string): string {
  const sections: string[] = [];
  if (graph) sections.push(`The current knowledge graph:\n${graph}`);
  walk(tree, tree.root, 0, sections);
  return sections.join("\n\n");
}

function walk(
  tree: ThreadTree,
  id: ThreadId,
  depth: number,
  out: string[],
): void {
  const node = tree.get(id);
  const origin = node.origin;
  const quote = origin
    ? anchorText(origin.anchor, tree.get(origin.anchor.thread).thread.messages)
    : "";
  const header = origin
    ? `Follow-up thread (depth ${depth}) on "${quote}" - the user said: ${actionLabel(origin.action)}`
    : "The task session:";
  out.push(`${header}\n${transcript(node.thread.messages)}`);
  for (const child of node.children) walk(tree, child, depth + 1, out);
}

function transcript(messages: ReadonlyArray<Message>): string {
  return messages
    .map((m) => `${m.role === "user" ? "User" : "Assistant"}: ${line(m)}`)
    .join("\n\n");
}

function line(message: Message): string {
  return message.type === "text"
    ? message.text
    : `[called tool ${message.call.name} with ${message.call.inputJson}]`;
}

/** How the thread was opened, shown at the top of its pane so the user can see
 * what they asked for. */
export function actionLabel(action: Action): string {
  switch (action.type) {
    case "explain":
      return "I don't understand this.";
    case "quiz":
      return "Quiz me on this.";
    case "query":
      return action.text;
  }
}

function question(action: Action): string {
  switch (action.type) {
    case "explain":
      return "They said they don't understand this. Explain what it means and why it is there.";
    case "quiz":
      return "They asked to be quizzed on this. Ask one question that checks whether they understand it, and wait for their answer.";
    case "query":
      return `They asked: ${action.text}`;
  }
}

import { expect, it } from "vitest";
import { KnowledgeGraph, LEVELS } from "./graph.ts";
import {
  EXTRACT_SYSTEM,
  LEARNING_SYSTEM,
  renderTree,
  seedTurn,
} from "./prompt.ts";
import type { Anchor, ThreadId } from "./selection.ts";
import { type Socket, Thread } from "./thread.ts";
import { ThreadTree } from "./threads.ts";

const messages = [
  { type: "text" as const, role: "user" as const, text: "build a parser" },
  {
    type: "text" as const,
    role: "assistant" as const,
    text: "I used a recursive descent approach.",
  },
  { type: "text" as const, role: "user" as const, text: "thanks" },
] as const;

const at = (
  startMsg: number,
  start: number,
  endMsg: number,
  end: number,
): Anchor => ({
  thread: "root" as ThreadId,
  start: { msg: startMsg, offset: start },
  end: { msg: endMsg, offset: end },
});

it("quotes the selection verbatim", () => {
  const seed = seedTurn(undefined, messages, at(1, 9, 1, 26), {
    type: "explain",
  });
  expect(seed).toContain('The user then selected: "recursive descent"');
});

it("quotes a selection spanning two messages", () => {
  const seed = seedTurn(undefined, messages, at(0, 6, 1, 6), { type: "quiz" });
  expect(seed).toContain('selected: "a parser\n\nI used"');
});

it("truncates the transcript after the message containing the selection end", () => {
  const seed = seedTurn(undefined, messages, at(1, 0, 1, 5), {
    type: "explain",
  });
  expect(seed).toContain("build a parser");
  expect(seed).not.toContain("thanks");
});

it("distinguishes the three actions and carries a query through", () => {
  const anchor = at(1, 9, 1, 26);
  const explain = seedTurn(undefined, messages, anchor, { type: "explain" });
  const quiz = seedTurn(undefined, messages, anchor, { type: "quiz" });
  const query = seedTurn(undefined, messages, anchor, {
    type: "query",
    text: "why not a parser generator?",
  });
  expect(new Set([explain, quiz, query]).size).toBe(3);
  expect(query).toContain("why not a parser generator?");
});

it("composes flat at depth, oldest section first", () => {
  const root = seedTurn(undefined, messages, at(1, 9, 1, 26), {
    type: "explain",
  });
  const level1 = [
    {
      type: "text" as const,
      role: "assistant" as const,
      text: "It parses top-down.",
    },
  ] as const;
  const depth2 = seedTurn(root, level1, at(0, 10, 0, 18), { type: "quiz" });

  expect(depth2).toBe(
    [
      "User: build a parser",
      "",
      "Assistant: I used a recursive descent approach.",
      "",
      'The user then selected: "recursive descent"',
      "They said they don't understand this. Explain what it means and why it is there.",
      "",
      "Assistant: It parses top-down.",
      "",
      'The user then selected: "top-down"',
      "They asked to be quizzed on this. Ask one question that checks whether they understand it, and wait for their answer.",
    ].join("\n"),
  );
  expect(depth2.startsWith(root)).toBe(true);
  expect(depth2.split("build a parser")).toHaveLength(2);

  const level2 = [
    {
      type: "text" as const,
      role: "assistant" as const,
      text: "Question: what is a token?",
    },
  ] as const;
  const depth3 = seedTurn(depth2, level2, at(0, 0, 0, 8), {
    type: "query",
    text: "what?",
  });
  expect(depth3.startsWith(depth2)).toBe(true);
  expect(depth3.split("build a parser")).toHaveLength(2);
  expect(depth3.split("It parses top-down")).toHaveLength(2);
});

it("names the get tool and the scale in the learning system prompt", () => {
  expect(LEARNING_SYSTEM).toContain("`get`");
  for (const label of LEVELS) expect(LEARNING_SYSTEM).toContain(label);
});

it("renders the graph into a top-level seed, and only there", () => {
  const graph = new KnowledgeGraph();
  graph.putNode({
    title: "recursive descent",
    description: "top-down parsing",
    notes: "asked about it",
    level: 2,
  });
  const rendered = graph.render();
  const top = seedTurn(
    undefined,
    messages,
    at(1, 9, 1, 26),
    { type: "explain" },
    rendered,
  );
  expect(top).toContain(rendered);
  const deeper = seedTurn(
    top,
    messages,
    at(1, 9, 1, 26),
    { type: "explain" },
    rendered,
  );
  expect(deeper.split(rendered)).toHaveLength(2);
});

const silentSocket: Socket = { send() {}, addEventListener() {} };

it("renders the whole tree, keeping each child's action and anchor text", () => {
  const root = new Thread(silentSocket, { initialTurns: [] });
  const tree = new ThreadTree(silentSocket, root, () => {});
  void root.send("build a parser");
  const anchor: Anchor = {
    thread: tree.root,
    start: { msg: 0, offset: 6 },
    end: { msg: 0, offset: 14 },
  };
  tree.open(anchor, { type: "quiz" });

  const rendered = renderTree(tree, "the graph");
  expect(rendered).toContain("build a parser");
  expect(rendered).toContain("a parser");
  expect(rendered).toContain("Quiz me on this.");
  expect(rendered).toContain("the graph");
});

it("tells the extraction agent what a node is and where misconceptions go", () => {
  expect(EXTRACT_SYSTEM).toContain("One node per concept");
  expect(EXTRACT_SYSTEM).toContain("`notes`");
});

import type Anthropic from "@anthropic-ai/sdk";
import type { ClientMessage } from "@edulab/iso/protocol.ts";
import { expect, it } from "vitest";
import { KnowledgeGraph } from "./graph.ts";
import { readTools } from "./graph-tools.ts";
import type { Anchor } from "./selection.ts";
import { type Socket, Thread } from "./thread.ts";
import { ThreadTree } from "./threads.ts";

class FakeSocket implements Socket {
  readonly sent: ClientMessage[] = [];
  private readonly listeners: ((e: MessageEvent<string>) => void)[] = [];

  send(data: string) {
    this.sent.push(JSON.parse(data) as ClientMessage);
  }

  addEventListener(
    _type: "message",
    listener: (e: MessageEvent<string>) => void,
  ) {
    this.listeners.push(listener);
  }

  get last(): ClientMessage {
    const last = this.sent[this.sent.length - 1];
    if (!last) throw new Error("nothing sent");
    return last;
  }

  deliver(event: Anthropic.RawMessageStreamEvent) {
    const requestId = this.last.requestId;
    const data = JSON.stringify({ type: "event", requestId, event });
    for (const listener of [...this.listeners]) {
      listener(new MessageEvent("message", { data }));
    }
  }

  yields(input: Record<string, unknown>) {
    this.deliver({
      type: "content_block_start",
      index: 0,
      content_block: {
        type: "tool_use",
        id: "call-1",
        name: "yield",
        input: {},
        caller: { type: "direct" },
      },
    });
    this.deliver({
      type: "content_block_delta",
      index: 0,
      delta: { type: "input_json_delta", partial_json: JSON.stringify(input) },
    });
    this.deliver({ type: "content_block_stop", index: 0 });
    this.deliver({ type: "message_stop" } as Anthropic.RawMessageStreamEvent);
  }
}

const SCHEMA: Anthropic.Tool.InputSchema = {
  type: "object",
  properties: { grade: { type: "string" } },
  required: ["grade"],
};

/** A tree whose root has one committed user turn, so there is something to
 * anchor a child onto. */
function setup() {
  const socket = new FakeSocket();
  const root = new Thread(socket, { initialTurns: [] });
  const tree = new ThreadTree(socket, root, () => {});
  void root.send("the quick brown fox");
  const anchor: Anchor = {
    thread: tree.root,
    start: { msg: 0, offset: 0 },
    end: { msg: 0, offset: 9 },
  };
  return { socket, tree, anchor };
}

it("passes a yield schema to a child and surfaces its settled value", async () => {
  const { socket, tree, anchor } = setup();
  const child = tree.open(anchor, { type: "quiz" }, { yieldSchema: SCHEMA });
  const turn = tree.get(child).thread.start();

  expect(socket.last.params.tools).toEqual([
    { name: "yield", description: expect.any(String), input_schema: SCHEMA },
  ]);

  socket.yields({ grade: "got it" });
  expect(await turn).toEqual({
    type: "yielded",
    value: { type: "structured", value: { grade: "got it" } },
  });
  expect(tree.result(child)).toEqual({
    type: "yielded",
    value: { type: "structured", value: { grade: "got it" } },
  });
});

it("offers no tools to a child opened without any", () => {
  const { socket, tree, anchor } = setup();
  const child = tree.open(anchor, { type: "explain" });
  void tree.get(child).thread.start();
  expect(socket.last.params.tools).toBeUndefined();
});

it("sends a child's tools on its first request, and none for the root task thread", () => {
  const { socket, tree, anchor } = setup();
  expect(socket.last.params.tools).toBeUndefined();
  const graph = new KnowledgeGraph();
  const child = tree.open(
    anchor,
    { type: "explain" },
    {
      tools: readTools(graph),
      graph: graph.render(),
    },
  );
  void tree.get(child).thread.start();
  expect(socket.last.params.tools?.map((t) => t.name)).toEqual(["get"]);
  expect(tree.get(child).thread.seed).toContain(graph.render());
});

